}

.chart {
    overflow: hidden;
    width: 100%;
    height: calc(100vh - 300px);
}

.change-btns {
    position: absolute;
    display: flex;
    height: 40px;
    user-select: none;
    z-index: 1;
}

.change-echarts {
    width: 48px;
    height: 32px;
    background: #079b9f11;
    border: 1px solid #079b9f;
    color: #079b9f;
    border-radius: 2px 0 0 2px;
    line-height: 32px;
    text-align: center;
    cursor: pointer;
}

.change-echarts1 {
    width: 48px;
    height: 32px;
    border: 1px solid #d9d9d9;
    border-radius: 0 2px 2px 0;
    line-height: 32px;
    text-align: center;
    cursor: pointer;
}

.table-wrap {
    width: 100%;
    height: calc(100% - 111px);
}

.fill {
